INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_0_0','白水诗','无名氏','先秦','浩浩白水。
倏倏之鱼。
君来召我。
我将安居。
国家未立。
从我焉如。',NULL,'','{"preface": "《列女传》曰：宁戚击牛角而商歌。甚悲。桓公异之。使管促迎之。宁戚称曰：浩浩乎白水。管仲不知所谓。不朝五日。而有忧色。其妾笑曰：人已语君矣。古有白水之诗云云。宁戚之欲得仕国家也。", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_0_1','白水诗','无名氏','先秦','浩浩者水。
育育者鱼。
未有室家。
而召我安居。',NULL,'','{"preface": "《管子》曰：桓公使管仲求宁戚。宁戚应之曰：浩浩乎。管仲不知。至中食而虑之。婢子曰：公何虑。管仲曰：公使我求宁戚。宁戚应我曰：浩浩乎。吾不识。婢子曰：诗有之云云。宁子其欲室乎。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_2','《后汉书》引逸诗','无名氏','先秦','皎皎练丝。
在所染之。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_0_3','佹诗','无名氏','先秦','天地易位。
四时易乡。
列星陨坠。
旦暮晦盲。
幽暗登昭。
日月下藏。
公正无私。
反见纵横。
志爱公利。
重楼疏堂。
无私罪人。
憼革二兵。
道德纯备。
谗口将将。
仁人绌约。
敖暴擅强。
天下幽险。
恐失世英。
龟龙为蝘蜓。
鸱枭为凤凰。
比干见刳。
孔子拘匡。
昭昭乎其知之明也。
郁郁乎其遇时之不祥也。
拂乎其欲礼义之大行也。
暗乎天下之晦盲也。
皓天不复。
忧无疆也。
千秋必反。
古之常也。
弟子勉学。
天不忘也。
圣人共手。
时几将矣。
念彼远方。
何其塞矣。
仁人绌约。
暴人衍矣。
忠臣危殆。
谗人般矣。
璇玉瑶珠。
不知佩也。
杂布与锦。
不知异也。
闾娵子奢。
莫之媒也。
嫫母力父。
是之喜也。
以盲为明。
以聋为聪。
以危为安。
以吉为凶。
呜呼上天。
曷维其同。',NULL,'','{"preface": "《荀子》曰：天下不治。请陈佹诗云云。与愚亦疑。愿闻反辞。其小歌也云云。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_4','峤诗','无名氏','先秦','何自南极。
至于北极。
绝境越国。
弗愁道远。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_0_5','《家语》引逸诗','无名氏','先秦','皇皇上天。
其命不忒。
天之以善。
必报其德。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_0_6','大唐歌','无名氏','先秦','舟张辟雍，
鸧鸧相从。
八风回回，
凤皇喈喈。',NULL,'','{"preface": "《尚书大传》曰：惟五祀。定钟石。论人声。鸟兽咸变。于是勃然兴韶于大麓之野。执事还归。二年䜎然。乃作大唐之歌。以声帝美。声成而彩凤至。故其乐曰：", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_0_7','子桑琴歌','无名氏','先秦','父邪母邪。
天乎人乎。',NULL,'','{"preface": "《庄子》曰：子舆与子桑友。而霖雨十日。子舆曰：子桑殆病矣。裹饭而往食之。至子桑之门。则若歌若哭。鼓琴曰云云。子舆入。曰：子之歌声。何故若是。曰：吾思夫使我至此极者而不得也。父母岂欲吾贫哉。天地岂私贫我哉。然而至此极者。命也。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_0_8','丰歌','无名氏','先秦','凤皇下丰。',NULL,'','{"preface": "《尚书中候》曰：周文王作丰。一朝扶老至者八十万户。草居陋然。歌曰：", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_0_9','五子歌','无名氏','先秦','皇祖有训。
民可近。
不可下。
民惟邦本。
本固邦宁。
予视天下愚夫愚妇。
一能胜予。
怨岂在明。
不见是图。
予临兆民。
懔乎若朽索之驭六马。
为人上者。
奈何不敬。
训有之。
内作色荒。
外作禽荒。
甘酒嗜音。
峻宇雕墙。
有一于此。
未或不亡。
惟彼陶唐。
有此冀方。
今失厥道。
乱其纪纲。
乃底灭亡。
明明我祖。
万邦之君。
有典有则。
贻厥子孙。
关石和钧。
王府则有。
荒坠厥绪。
覆宗绝祀。
呜呼曷归。
予怀之悲。
万姓仇予。
予将畴依。
郁陶乎予心。
颜厚有忸怩。
弗慎厥德。
虽悔可追。',NULL,'','{"preface": "《夏书》曰：太康失位。以逸豫灭厥德。黎民咸贰。乃盘游无度。畋于有洛之表。有穷后羿。因民弗忍。距于河。厥弟五人。御其母以从。徯于洛之汭。五子咸怨。述大禹之戒以作歌。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_10','《孔丛子》引遗谚','无名氏','先秦','尧舜千钟。
孔子百觚。
子路嗑嗑。
尚饮十榼。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_0_11','长水童谣','无名氏','先秦','城门当有血。
城没陷为湖。',NULL,'','{"preface": "神异传曰：由拳县。秦时长水县也。始皇时。县有童谣曰云云。有老妪闻之忧惧。旦往窥城门。门侍欲缚之。妪言其故。妪去后。门侍杀犬。以血涂门。忽有大水。长欲没县。主簿令干入白令。令见干曰：何忽作鱼。干又曰：明府亦作鱼。遂乃沦陷为谷矣。因目长水、城水曰谷水矣。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_0_12','丘陵歌','无名氏','先秦','登彼丘陵。
峛崺其阪。
仁道在迩。
求之若远。
遂迷不复。
自婴屯蹇。
喟然回虑。
题彼泰山。
郁确其高。
梁甫回连。
枳棘充路。
陟之无缘。
将伐无柯。
患兹蔓延。
惟以永叹。
涕霣潺湲。',NULL,'','{"preface": "《诗纪》此注本之风雅逸篇。案。陆贾新语慎微篇言孔子作公陵之歌。然无歌辞。○《孔丛子》曰：哀公使以璧如卫迎夫子。而不能赏用也。故夫子作丘陵之歌曰：", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_0_13','包山谣','无名氏','先秦','禹得金简玉字书。
藏洞庭包山湖。',NULL,'','{"preface": "《诗纪》云。见杨方《吴越春秋》。又引沈怀远南越志曰：牛女之分。扬州之末土也。爰有泰山。实曰秦望。又有石篑。峻起壁立。内有金简玉字。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_0_14','去鲁歌','无名氏','先秦','彼妇之口。
可以出走。
彼妇之谒。
可以死败。
盖优哉游哉。
维以卒岁。',NULL,'','{"preface": "《史记》曰：孔子相鲁。齐人遗女乐。季桓子受之。三日不听政。郊又不致膰俎于大夫。孔子遂行。宿乎屯。而师已送曰：夫子则非罪。孔子曰：吾歌可夫。歌曰云云。桓子闻之曰：夫子罪我以群婢故也。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_15','鬼谷子引古语','无名氏','先秦','女爱不蔽席。
男欢不尽轮。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_0_16','甘泉歌','无名氏','秦','运石甘泉口，
渭水不敢流。
千人唱，
万人讴，
金陵馀石大如塸。',NULL,'','{"preface": "三秦记曰：始皇作骊山陵。周回跨阴盘县界。水背陵障。使东西流。运大石于渭北渚。民怨之。作甘泉之歌曰：○逯案。二酉堂丛书本辛氏三秦记载此。张氏谓出太平《御览》。今检《御览》无此条。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_17','申包胥歌','无名氏','先秦','吴为无道。
封豕长蛇。
以食上国。
欲有天下。
政从楚起。
寡君出自草泽。
使来告急。',NULL,'','{"preface": "《吴越春秋》曰：子胥以吴兵伐楚。入郢。昭王出奔。申包胥乃之秦求救。倚哭于秦庭。七日七夜。口不绝声。哭已。歌曰云云。桓公大惊曰：楚有贤臣若此。吴犹欲灭之。寡人无臣若斯者。其亡无日矣。为赋无衣之诗。出师而送之。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_18','申叔仪乞粮歌','无名氏','先秦','佩玉蕊兮余无所系之。
旨酒一盛兮余与褐之父睨之。',NULL,'','{"preface": "《左传》曰：哀公十三年。公会单平公、晋定公、吴夫差于黄池。吴申叔仪乞粮于公孙有山氏曰云云。有山氏对曰：粱则无矣。粗则有之。若登首山以呼曰庚癸乎。则诺。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_0_19','乌鹊歌','无名氏','先秦','仰飞鸟兮乌鸢。
凌玄虚兮号翩翩。
集洲渚兮优恣。
啄虾矫翮兮云间。
任厥性兮往还。
妾无罪兮负地。
有何辜兮谴天。
帆帆独兮西往。
孰知返兮何年。
心惙惙兮若割。
泪泫泫兮双悬。
彼飞鸟兮鸢乌。
已回翔兮翕苏。
心在专兮素虾。
何居食兮江湖。
徊复翔兮游飏。
去复返兮于乎。
始事君兮去家。
终我命兮君都。
终来遇兮何辜。
离我国兮去吴。
妻衣褐兮为婢。
夫去冕兮为奴。
岁遥遥兮难极。
冤悲痛兮心恻。
肠千结兮服膺。
于乎哀兮忘食。
愿我身兮如鸟。
身翱翔兮矫翼。
去我国兮心摇。
情愤惋兮谁识。',NULL,'','{"preface": "《吴越春秋》曰：越王句践与大夫种、范蠡入臣于吴。群臣皆送至浙江之上。越王夫人乃据船哭。顾乌鹊啄江渚之虾。飞去复来。因哭而歌之曰云云。又哀吟曰云云。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_20','龙蛇歌','无名氏','先秦','龙欲上天。
五蛇为辅。
龙已升云。
四蛇各入其宇。
一蛇独怨。
终不见处所。',NULL,'','{"preface": "《史记》曰：晋国复而文公以得归。赏从亡者。未至介子推。推亦不言禄。从者怜之。乃悬书宫门曰云云。文公出。见其书曰：此介子推也。使人召之。则亡。入绵上山中。于是文公环绵上山而封之。以为介推田。号曰介山。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_21','龙蛇歌','无名氏','先秦','有龙于飞，
周遍天下。
五蛇从之，
为之承辅。
龙返其乡，
得其处所。
四蛇从之，
得其雨露。
一蛇羞之，
槁死于中野。',NULL,'','{"preface": "《吕氏春秋》曰：晋文公反国。介子推不肯受赏。自为赋《诗》曰云云。悬书公门而伏于山下。文公闻之曰：嘻。此必介子推也。○逯案。龙蛇歌分见《吕氏春秋》、《史记》、《说苑》、《新序》、《淮南子》注及琴操等。辞各有异。《诗纪》均入古逸。今分别编此及汉诗中。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_22','龙蛇歌','无名氏','先秦','有龙矫矫。
顷失其所。
五蛇从之。
周遍天下。
龙饥无食。
一蛇割股。
龙返其渊。
安其壤土。
四蛇入穴。
皆有处所。
一蛇无穴。
号于中野。',NULL,'','{"preface": "《说苑》曰：文公即位。赏不及推。推且出怨言。不食其食。推从者怜之。乃悬书宫门曰云云。文公出。见书。曰：嗟。此介子推也。使人召之。则亡。入绵上山中。于是文公表绵上山中而封之。以为介推田。号曰介山。", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_0_23','优孟歌','无名氏','先秦','山居耕田苦。
难以得食。
起而为吏。
身贪鄙者馀财。
不顾耻辱。
身心家室富。
又恐受赇枉法为奸触大罪。
身死而家灭。
贪吏安可为也。
念为廉吏。
奉法守职。
竟死不敢为非。
廉吏安可为也。',NULL,'','{"preface": "《史记》曰：楚相孙叔敖病且死。属其子曰：若贫困。往见优孟。居数年。其子贫困负薪。逢优孟。曰：我孙叔敖子也。父死时。属我贫困往见优孟。孟即为孙叔敖衣冠。抵掌谈语。岁馀。像孙叔敖。楚王置酒。优孟前为寿。庄王大惊。以为孙叔敖复生也。欲以为相。优孟曰：楚相不足为也。孙叔敖为楚相。尽忠为廉。王得以伯。今死。其子贫困负薪以自饮食。必如孙叔敖。不如自杀。因歌曰云云。庄王乃召孙叔敖子。封之寝丘。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_24','岁莫歌','无名氏','先秦','岁已莫矣，
而禾不穫，
忽忽兮若之何。
岁已寒矣，
而役不罢，
惙惙兮如之何。',NULL,'','{"preface": "《晏子春秋》曰：景公筑长庲之台。晏子侍坐。觞三行。晏子起舞曰云云。舞三而涕下沾襟。景公惭焉。为之罢长庲之役。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_25','成人歌','无名氏','先秦','蚕则绩而蟹有匡。
范则冠而蝉有绥。
兄则死而子皋为之衰。',NULL,'','{"preface": "檀弓曰：成人有其兄死而不为衰者。闻高子皋为成宰。遂为衰。成人歌曰：", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_0_26','成王冠辞','无名氏','先秦','令月吉日。
王始加元服。
去王幼志服衮职。
钦若昊天。
六合是式。
率尔祖考。
永永无极。',NULL,'','{"preface": "《家语》曰：武王崩。成王年十三而嗣立。周公摄政以治天下。冠成王而朝于祖。以见诸侯。周公命祝雍作颂曰：", "note": ""}','辞赋','hefengbao/jingmo-data3'),
('rd3_0_27','霜叶飞 重九早赴沪上','石任之','当代','二城朝霁。
秋阴杳，
纤尘犹湿空翠。
九华初服未登临，
况试题糕字。
谢羽客，
相呼异地，
云间归路殊迢递。
纵彩笔堪传，
锦袖冷，
红笺削减，
赏心潜替。
候馆物序萧条，
云浆谁酿，
百虑惟此能制。
枕衾不惯起频看，
照影惊憔悴。
四壁悄，
浑如梦寐。
年来怕见终飘坠。
但晓夕成流水，
霜结疏棂，
旧怀犹是。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_0_28','成相杂辞','无名氏','先秦','请成相。
世之殃。
愚暗愚暗堕贤良。
人主无贤。
如瞽无相何伥伥。
请布基。
慎圣人。
愚而自专事不治。
主忌苟胜。
群臣莫谏必逢灾。
论臣过。
反其施。
尊主安国尚贤义。
拒谏饰非。
愚而上同国必祸。
曷谓罢。
国多私。
比周还主党与施。
远贤近谗。
忠臣蔽塞主势移。
曷谓贤。
明君臣。
上能尊主爱下民。
主诚听之。
天下为一四海宾。
主之孽。
谗人达。
贤能遁逃国乃蹶。
愚以重愚。
暗以重暗成为桀。
世之灾。
妒贤能。
飞廉知政任恶来。
卑其志意。
大其园囿高其台。
武王怒。
师牧野。
纣卒易乡启乃下。
武王善之。
封之于宋立其祖。
世之衰。
谗人归。
比干见刳箕子累。
武王诛之。
吕尚招麾殷民怀。
世之祸。
恶贤士。
子胥见杀百里徙。
穆公得之。
